#!/usr/bin/env bash
# Rebuild earcut_wasm.mjs from earcut_wasm.cpp.
#
# You only need this if you change the C++ -- the built module is committed, so
# a normal checkout builds and tests without Emscripten installed.
#
# Requires Emscripten (`brew install emscripten`, or emsdk). Built with 6.0.8.
#
#   ./build.sh && git diff --stat earcut_wasm.mjs
#
# SINGLE_FILE inlines the wasm as base64 inside the ES module. That costs ~30%
# over a side-by-side .wasm, and buys the only thing that matters here: the
# viewer stays a single esbuild bundle with no second artifact to serve, no
# path to resolve at runtime, and nothing for a host like Prism to vendor
# beyond the JS it already vendors.
set -euo pipefail
cd "$(dirname "$0")"

em++ -std=c++17 -O3 -flto \
    -sMODULARIZE=1 -sEXPORT_ES6=1 -sENVIRONMENT=web,worker -sSINGLE_FILE=1 \
    -sALLOW_MEMORY_GROWTH=1 -sINITIAL_MEMORY=16777216 \
    -sFILESYSTEM=0 -sASSERTIONS=0 -sINVOKE_RUN=0 -sEXIT_RUNTIME=0 \
    -sEXPORTED_FUNCTIONS='["_ec_coords","_ec_run_one_f32","_ec_verts"]' \
    -sEXPORTED_RUNTIME_METHODS='["HEAPF64","HEAPF32"]' \
    -o earcut_wasm.mjs earcut_wasm.cpp

# The repo type-checks JS (`checkJs: true`), and Emscripten's glue is minified
# machine output that will never satisfy it -- same reason ../earcut/earcut.js
# carries these. Prepended here so a rebuild does not silently drop them.
printf '%s\n' \
    '/* eslint-disable */' \
    '// @ts-nocheck' \
    '// Generated by ./build.sh from earcut_wasm.cpp -- do not edit.' \
    | cat - earcut_wasm.mjs > earcut_wasm.mjs.tmp
mv earcut_wasm.mjs.tmp earcut_wasm.mjs

echo "built earcut_wasm.mjs ($(wc -c < earcut_wasm.mjs) bytes)"
